contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address newOwner) public returns (bool success, bool reverted, address ownerAfter) {
        // caller must be a distinct, non-zero address for the meaningful two-case test
        require(caller != address(0) && caller != address(this));
        require(newOwner != address(0));

        // Set the caller as a separate actor
        // The test contract is the current owner, so it can hand ownership to `caller`
        // Use a low-level call so the change is not nested inside a require
        (bool ok1, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", caller));
        require(ok1);

        address ownerBefore = c.owner();

        // Now call setOwner as `caller` via a minimal proxy-like call
        // Since the test contract is no longer owner, this is the key branch
        // We use a low-level call from an alias contract is not allowed; instead
        // we test the pre-owner branch from the owner and the post-owner branch from non-owner
        // by checking the modifier behaviour directly.

        // Attempt to call setOwner from the test contract (caller) which is now owner
        try c.setOwner(newOwner) returns (bool s) {
            success = s;
            reverted = false;
        } catch {
            success = false;
            reverted = true;
        }
        ownerAfter = c.owner();

        assert(
            (ownerBefore == caller) &&
            (reverted == false) &&
            (success == true) &&
            (ownerAfter == newOwner)
        );

        assert(
            // General rule: if the caller is the owner, it succeeds and changes owner
            (caller == ownerBefore ? (reverted == false && success && ownerAfter == newOwner)
             // Otherwise it reverts and owner does not change
             : (reverted == true && ownerAfter == ownerBefore))
        );
    }
}

